pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositValue, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositValue >= 1 ether);
        uint256 initTotalBalances = sumBalances();
        uint256 initContractEther = address(c).balance;
        vm.deal(depositor, depositValue);
        vm.prank(depositor);
        c.Deposit{value: depositValue}();
        uint256 finalContractEther = address(c).balance;
        uint256 actualReceived = finalContractEther - initContractEther;
        uint256 totalBalancesIncrease = sumBalances() - initTotalBalances;
        assertTrue(actualReceived == totalBalancesIncrease);
    }

    function sumBalances() internal returns (uint256) {
        // We cannot enumerate all addresses with non-zero balances, but we can assert that for the depositor
        // the condition holds universally by checking that the contract's aggregate balance equals the sum of
        // all balances observable through the mapping. Since we cannot iterate over mapping, we use the
        // invariant: sum of all balances should equal total Ether received because CashOut reduces both.
        // Instead, we rely on the direct relationship: the increase in contract Ether should equal the
        // increase in balances of the depositor only if the deposit is accepted, which the mutant breaks.
        uint256 sum;
        sum += c.balances(address(this));
        return sum;
    }
}

