        uint256 user1BalAfterDeposit = c.balances(user1);

        // ensure user1 can only cash out what they have
        uint256 actualCashOut = cashOutAmount > user1BalAfterDeposit ? user1BalAfterDeposit : cashOutAmount;
        if (actualCashOut == 0) {
